declarations.type_pp:
∀ {α β Γ₀ Γ₁ : Type} [inst : Fintype Γ₀] [inst_1 : Fintype Γ₁] {ea : Computability.Encoding α Γ₀}
  {eb : Computability.Encoding β Γ₁} {f : α → β} (hf : Counting.Computation.PolyTime ea eb f) (a : α),
  instLENat.le (eb.encode (f a)).length (Polynomial.eval (ea.encode a).length hf.outputLengthPolynomial)

declarations.type_pp_all:
∀ {α β Γ₀ Γ₁ : Type} [inst : Fintype.{0} Γ₀] [inst_1 : Fintype.{0} Γ₁] {ea : Computability.Encoding.{0, 0} α Γ₀}
  {eb : Computability.Encoding.{0, 0} β Γ₁} {f : α → β}
  (hf : @Counting.Computation.PolyTime α β Γ₀ Γ₁ inst inst_1 ea eb f) (a : α),
  @LE.le.{0} Nat instLENat (@List.length.{0} Γ₁ (@Computability.Encoding.encode.{0, 0} β Γ₁ eb (f a)))
    (@Polynomial.eval.{0} Nat Nat.instSemiring (@List.length.{0} Γ₀ (@Computability.Encoding.encode.{0, 0} α Γ₀ ea a))
      (@Counting.Computation.PolyTime.outputLengthPolynomial α β Γ₀ Γ₁ inst inst_1 ea eb f hf))

declarations.type_pp:
∀ {α Γ : Type} [inst : Fintype Γ] {ea : Computability.Encoding α Γ} {f : α → Nat}
  (w : Counting.Complexity.SharpPWitness ea f) (a : α),
  instLENat.le (f a) (instHPow.hPow 2 (Polynomial.eval (ea.encode a).length w.witnessLength))

∀ {α β Γα Γβ : Type} [inst : Fintype Γα] [inst_1 : Fintype Γβ] {ea : Computability.Encoding α Γα}
  {eb : Computability.Encoding β Γβ} {f : α → Nat} {g : β → Nat}
  (r : Counting.Complexity.ParsimoniousReduction ea eb f g) (a : α),
  instLENat.le (eb.encode (r.map a)).length (Polynomial.eval (ea.encode a).length r.machine.outputLengthPolynomial)

