∀ {α β Γα Γβ Γn : Type} [inst : Fintype.{0} Γα] [inst_1 : Fintype.{0} Γβ] [inst_2 : Fintype.{0} Γn]
  {ea : Computability.Encoding.{0, 0} α Γα} {eb : Computability.Encoding.{0, 0} β Γβ}
  {en : Computability.Encoding.{0, 0} Nat Γn} {f : α → Nat} {g : β → Nat}
  (r : @Counting.Complexity.ParsimoniousReduction α β Γα Γβ inst inst_1 ea eb f g)
  (hg : @Counting.Computation.InFP β Nat Γβ Γn inst_1 inst_2 eb en g),
  @Counting.Computation.InFP α Nat Γα Γn inst inst_2 ea en f

∀ {α β γ Γα Γβ Γγ : Type} [inst : Fintype.{0} Γα] [inst_1 : Fintype.{0} Γβ] [inst_2 : Fintype.{0} Γγ]
  {ea : Computability.Encoding.{0, 0} α Γα} {eb : Computability.Encoding.{0, 0} β Γβ}
  {ec : Computability.Encoding.{0, 0} γ Γγ} {C : (α → Nat) → Prop} {g : β → Nat} {h : γ → Nat}
  (hg : @Counting.Complexity.HardFor α β Γα Γβ inst inst_1 ea eb C g)
  (r : @Counting.Complexity.ParsimoniousReduces β γ Γβ Γγ inst_1 inst_2 eb ec g h),
